// Solution for: Candidate Ranking Engine
import java.util.*; public class W51_q5 {static class Candidate implements Comparable<Candidate>{String name;double cgpa;int coding;Candidate(String n,double g,int c){name=n;cgpa=g;coding=c;}boolean eligible(){return cgpa>=7.0&&coding>=30;}double score(){return cgpa*10+coding;}public int compareTo(Candidate o){return Double.compare(o.score(),score());}public String toString(){return name+" "+String.format("%.2f",score());}}public static void main(String[]z){Candidate[] a={new Candidate("Aisha",8.2,40),new Candidate("Rohit",6.8,65),new Candidate("Neena",6.8,90),new Candidate("Karan",7.5,28)};Candidate[] b=Arrays.stream(a).filter(Candidate::eligible).toArray(Candidate[]::new);Arrays.sort(b);for(Candidate c:b)System.out.println(c);}}
